import { useState } from 'react';
import { signUp, logIn } from '../lib/authApi';

export default function LoginPage() {
  const [mode, setMode] = useState('login');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    setError('');
    setBusy(true);
    try {
      if (mode === 'login') await logIn(username, password);
      else await signUp(username, password);
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="login-page">
      <div className="login-page__logo" aria-hidden="true" />
      <h1 className="text-main-heading">Right On Queue</h1>
      <form onSubmit={submit}>
        <label className="text-small">
          Username
          <input value={username} onChange={(e) => setUsername(e.target.value)} required />
        </label>
        <label className="text-small">
          Password
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            minLength={6}
          />
        </label>
        {error && <p className="login-page__error text-small">{error}</p>}
        <button type="submit" className="login-page__submit" disabled={busy}>
          {mode === 'login' ? 'Login' : 'Create account'}
        </button>
      </form>
      <button
        type="button"
        className="login-page__toggle text-small"
        onClick={() => {
          setError('');
          setMode(mode === 'login' ? 'signup' : 'login');
        }}
      >
        {mode === 'login' ? 'Need an account? Sign up' : 'Have an account? Log in'}
      </button>
    </div>
  );
}
